import json,re
from pathlib import Path
cf=json.loads(Path('/root/DATA/products/CoachForce.json').read_text())

def iter_texts(item):
    m=item.get('Message',{})
    u=m.get('User',{})
    if u.get('text'): yield ('msg',u.get('utterranceID') or item.get('id'), u.get('userId'), u.get('timestamp'), u.get('text'))
    for r in item.get('ThreadReplies',[]) or []:
        uu=r.get('User',{})
        if uu.get('text'): yield ('reply',uu.get('utterranceID'), uu.get('userId'), uu.get('timestamp'), uu.get('text'))

terms=[re.compile(r'cofoaix_market_research_report',re.I), re.compile(r'market research report',re.I), re.compile(r'cofoaix.*research',re.I)]
for pat in terms:
    found=0
    for item in cf['slack']:
        for kind,uid,user,ts,text in iter_texts(item):
            if pat.search(text):
                print('PAT',pat.pattern,'->',kind,uid,user,ts,text[:200].replace('\n',' '))
                found+=1
                if found>=5: break
        if found>=5: break
    if found==0:
        print('PAT',pat.pattern,'-> none')
PY", "security_risk": "LOW", "summary": "Search nested Slack texts for market research report mentions"}

