import json
from pathlib import Path
pf=json.loads(Path('/root/DATA/products/PersonalizeForce.json').read_text())

TARGET_IDS=set([
 '20260908-0-0853d','20260902-0-ba911','20260724-0-7bd7a','20260820-0-ded3c','20260820-9-f9e5f','20260820-10-b2525','20260820-11-b059e','20260810-0-bb012','20260810-7-b0f02','20260810-8-a3bbd','20260922-0-0ed21',
 '20260803-0-2fe0f','20260926-0-3b27f','20260928-0-fa2c5'
])

# Build lookup of all utterranceIDs to their container and text

def iter_entries(item):
    m=item.get('Message',{})
    u=m.get('User',{})
    if u.get('utterranceID'):
        yield item, u
    for r in item.get('ThreadReplies',[]) or []:
        uu=r.get('User',{})
        if uu.get('utterranceID'):
            yield item, uu

found=0
for item in pf['slack']:
    for container,u in iter_entries(item):
        uid=u['utterranceID']
        if uid in TARGET_IDS:
            print('===',uid,'channel',container.get('Channel',{}).get('name'))
            print('user',u.get('userId'),'time',u.get('timestamp'))
            print(u.get('text'))
            found+=1
print('found',found,'of',len(TARGET_IDS))
